def minimumRunnsToAdd(n, crystals, flowFrom, flowTo):
    # Build the graph
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for u, v in zip(flowFrom, flowTo):
        graph[u].append(v)

    # Use BFS to find all nodes reachable from crystals
    visited = [False] * n
    queue = deque(crystals)
    for c in crystals:
        visited[c] = True

    while queue:
        node = queue.popleft()
        for nei in graph[node]:
            if not visited[nei]:
                visited[nei] = True
                queue.append(nei)

    # Count number of unreachable components
    def dfs(u, mark):
        stack = [u]
        while stack:
            node = stack.pop()
            mark[node] = True
            for nei in graph[node]:
                if not mark[nei]:
                    stack.append(nei)

    result = 0
    mark = visited[:]
    for i in range(n):
        if not mark[i]:
            # This is a new unreachable component, start DFS from here
            dfs(i, mark)
            result += 1

    return result
